<template>
  <div class="storefront min-h-screen pb-28 text-slate-950 md:pb-10">
    <header class="store-header"><div class="mx-auto flex max-w-6xl items-center justify-between px-4 py-4 md:px-8">
      <div class="flex min-w-0 items-center gap-3"><img v-if="store.logoUrl" :src="store.logoUrl" alt="" class="h-11 w-11 rounded-2xl object-cover" /><div v-else class="store-mark" aria-hidden="true">P</div><div class="min-w-0"><p class="truncate text-lg font-black">{{ store.name || 'PedeVisse' }}</p><p class="text-xs font-semibold text-slate-500">{{ meta.label }} · {{ store.isOpen === false ? 'Fechado' : 'Aberto agora' }}</p></div></div>
      <button class="cart-button" type="button" aria-label="Abrir carrinho" @click="drawerOpen = true"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 4h2l2.1 10.1a2 2 0 0 0 2 1.6h7.8a2 2 0 0 0 1.9-1.4L21 8H7M10 20h.01M17 20h.01" /></svg><span v-if="cart.count" class="cart-count">{{ cart.count }}</span></button>
    </div></header>

    <main>
      <section class="hero mx-auto max-w-6xl px-4 pt-7 md:px-8 md:pt-12">
        <div class="hero-copy"><p class="availability"><span></span>{{ store.isOpen === false ? 'Pedidos pausados' : 'Entrega e retirada disponíveis' }}</p><h1>{{ store.heroTitle || 'Tudo o que você precisa, perto de casa.' }}</h1><p>{{ store.heroDescription || 'Escolha seus produtos, monte o carrinho e faça seu pedido em poucos minutos.' }}</p><button class="primary-action" type="button" @click="scrollToCatalog">Ver produtos</button></div>
        <div class="hero-display" aria-hidden="true"><div class="display-orbit orbit-one"></div><div class="display-orbit orbit-two"></div><div class="display-box"><svg viewBox="0 0 64 64"><path d="M11 24h42l-4 31H15l-4-31Z"/><path d="M23 26V18a9 9 0 0 1 18 0v8"/><path d="M22 37h20M22 45h13"/></svg></div><span class="display-chip chip-a">{{ categories[0]?.name || 'Destaques' }}</span><span class="display-chip chip-b">{{ categories[1]?.name || meta.catalogLabel }}</span></div>
      </section>

      <section class="service-strip mx-auto max-w-6xl px-4 md:px-8" aria-label="Benefícios da loja">
        <div><span class="service-icon">✓</span><p><strong>Compra simples</strong><small>Escolha em poucos toques</small></p></div>
        <div><span class="service-icon">↗</span><p><strong>Atendimento próximo</strong><small>Comércio local de confiança</small></p></div>
        <div><span class="service-icon">⌁</span><p><strong>Pedido organizado</strong><small>Revise tudo no carrinho</small></p></div>
      </section>

      <section id="catalogo" class="catalog mx-auto max-w-6xl px-4 pt-12 md:px-8 md:pt-16">
        <div class="catalog-heading"><div><h2>{{ meta.catalogLabel }}</h2><p>{{ filteredProducts.length }} {{ filteredProducts.length === 1 ? 'item encontrado' : 'itens encontrados' }}</p></div><div class="store-facts"><span>Taxa {{ money(store.deliveryFee || 0) }}</span><span>Pedido mín. {{ money(store.minOrder || 0) }}</span></div></div>
        <label class="search-box"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m16 16 4 4"/></svg><span class="sr-only">Buscar produtos</span><input v-model.trim="query" type="search" placeholder="Buscar por nome ou descrição" /><button v-if="query" type="button" aria-label="Limpar busca" @click="query = ''">×</button></label>
        <div class="category-strip" role="tablist" aria-label="Categorias"><button :class="{ active: activeCategory === 'all' }" type="button" @click="activeCategory = 'all'">Todos</button><button v-for="category in categories" :key="category.id" :class="{ active: activeCategory === category.id }" type="button" @click="activeCategory = category.id">{{ category.name }}</button></div>
        <div v-if="loading" class="product-grid" aria-label="Carregando produtos"><div v-for="n in 6" :key="n" class="product-card skeleton"></div></div>
        <div v-else-if="filteredProducts.length" class="product-grid">
          <article v-for="product in filteredProducts" :key="product.id" class="product-card" :class="{ unavailable: !product.isAvailable }"><div class="product-image"><img v-if="imageFor(product.imageUrl)" :src="imageFor(product.imageUrl)" :alt="product.name" /><svg v-else viewBox="0 0 64 64" aria-hidden="true"><path d="M15 21h34l-3 33H18l-3-33Z"/><path d="M24 22v-5a8 8 0 0 1 16 0v5"/></svg><span v-if="product.requiresPrescription" class="prescription-badge">Requer receita</span></div><div class="product-body"><h3>{{ product.name }}</h3><p>{{ [product.description, product.unitLabel].filter(Boolean).join(' · ') || 'Consulte os detalhes deste produto.' }}</p><div class="product-footer"><strong>{{ money(product.price) }}</strong><button type="button" :disabled="!product.isAvailable || store.isOpen === false" :aria-label="`Adicionar ${product.name}`" @click="add(product)">+</button></div><p v-if="!product.isAvailable" class="unavailable-label">Indisponível no momento</p></div></article>
        </div>
        <div v-else class="empty-state"><h3>Nenhum produto encontrado</h3><p>Tente outra busca ou escolha uma categoria diferente.</p><button type="button" @click="clearFilters">Limpar filtros</button></div>
      </section>
    </main>

    <Transition name="fade"><button v-if="drawerOpen" class="drawer-backdrop" type="button" aria-label="Fechar carrinho" @click="drawerOpen = false"></button></Transition>
    <Transition name="drawer"><aside v-if="drawerOpen" class="cart-drawer" aria-label="Carrinho"><div class="drawer-header"><div><p>Seu carrinho</p><span>{{ cart.count }} {{ cart.count === 1 ? 'item' : 'itens' }}</span></div><button type="button" aria-label="Fechar" @click="drawerOpen = false">×</button></div><div v-if="cart.items.length" class="drawer-items"><div v-for="item in cart.items" :key="item.productId" class="drawer-item"><div class="drawer-item-copy"><strong>{{ item.name }}</strong><span>{{ money(item.price) }}<template v-if="item.unitLabel"> · {{ item.unitLabel }}</template></span><small v-if="item.requiresPrescription">Receita será solicitada no checkout.</small></div><div class="quantity"><button type="button" @click="cart.dec(item.productId)">−</button><span>{{ item.qty }}</span><button type="button" @click="cart.add({ id: item.productId, ...item })">+</button></div><button class="remove-item" type="button" @click="cart.remove(item.productId)">Remover</button></div></div><div v-else class="drawer-empty"><p>Seu carrinho está vazio.</p><span>Adicione um produto para começar.</span></div><div class="drawer-summary"><div><span>Subtotal</span><strong>{{ money(cart.total) }}</strong></div><router-link :to="{ name: 'customer.cart', params: { restaurantSlug: tenant.slug } }" class="checkout-link" :class="{ disabled: !cart.items.length }">Revisar carrinho</router-link></div></aside></Transition>
    <button v-if="cart.items.length" class="mobile-cart" type="button" @click="drawerOpen = true"><span>{{ cart.count }} {{ cart.count === 1 ? 'item' : 'itens' }}</span><strong>Ver carrinho · {{ money(cart.total) }}</strong></button>
  </div>
</template>

<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { api } from '../../api/client'
import { useCartStore } from '../../stores/cart'
import { useTenantStore } from '../../stores/tenant'
import { useUiStore } from '../../stores/ui'
import { commerceMeta } from '../../config/commerce'
import combo12 from '../../assets/combo-12-peças.jpg'
import sushiNatural from '../../assets/sushi-natural.jpg'
import sushiFrito from '../../assets/sushi-frito.jpg'
import temakiNatural from '../../assets/temaki-natural.jpg'
import temakiFrito from '../../assets/temaki-frito.jpg'
import yakissoba from '../../assets/yakissoba.jpg'
import pharmacyTablets from '../../assets/pharmacy-tablets-demo.png'
import pharmacyVitamins from '../../assets/pharmacy-vitamins-demo.png'
import pharmacyCare from '../../assets/pharmacy-care-demo.png'
const tenant = useTenantStore(); const cart = useCartStore(); const ui = useUiStore()
const categories = ref([]); const query = ref(''); const activeCategory = ref('all'); const drawerOpen = ref(false); const loading = ref(true)
const store = computed(() => tenant.restaurant || {}); const meta = computed(() => commerceMeta(store.value.commerceType))
const products = computed(() => categories.value.flatMap(category => (category.products || []).map(product => ({ ...product, categoryId: category.id }))))
const filteredProducts = computed(() => { const term = normalize(query.value); return products.value.filter(product => (activeCategory.value === 'all' || product.categoryId === activeCategory.value) && (!term || normalize(`${product.name} ${product.description || ''} ${product.unitLabel || ''}`).includes(term))) })
const assets = { 'asset:combo-12': combo12, 'asset:sushi-natural': sushiNatural, 'asset:sushi-frito': sushiFrito, 'asset:temaki-natural': temakiNatural, 'asset:temaki-frito': temakiFrito, 'asset:yakissoba': yakissoba, 'asset:pharmacy-tablets': pharmacyTablets, 'asset:pharmacy-vitamins': pharmacyVitamins, 'asset:pharmacy-care': pharmacyCare }
function imageFor(value) { return assets[value] || (value?.startsWith('http') ? value : '') }
function normalize(value) { return String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase() }
function money(value) { return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(value || 0) / 100) }
function scrollToCatalog() { document.querySelector('#catalogo')?.scrollIntoView({ behavior: 'smooth' }) }
function clearFilters() { query.value = ''; activeCategory.value = 'all' }
function add(product) { cart.add(product); ui.toast({ message: `${product.name} adicionado ao carrinho.` }) }
async function loadMenu() { if (!tenant.slug) return; loading.value = true; try { const { data } = await api.get(`/t/${encodeURIComponent(tenant.slug)}/public/menu`); categories.value = data.categories || [] } finally { loading.value = false } }
onMounted(async () => { cart.load(); await loadMenu() }); watch(() => tenant.slug, async () => { cart.load(); await loadMenu() })
</script>

